async function loadAdminSupport(root){const r=await api('/api/admin/support?status='+(state.ticketStatus||'OPEN'));root.innerHTML=`<section class="card glass"><div class="section-head">${adminBack()}<h3>💬 Поддержка</h3></div><div class="seg"><button data-ticket-filter="OPEN" class="${(state.ticketStatus||'OPEN')==='OPEN'?'active':''}">Открытые</button><button data-ticket-filter="ANSWERED" class="${state.ticketStatus==='ANSWERED'?'active':''}">Отвеченные</button><button data-ticket-filter="CLOSED" class="${state.ticketStatus==='CLOSED'?'active':''}">Закрытые</button></div><div class="list">${r.items.map(t=>`<div class="support-card"><div class="row"><div class="grow"><b>#${t.id} · ${esc(t.user)}</b><div class="sub">${new Date(t.created_at).toLocaleString()}</div></div><span class="pill ${t.status==='OPEN'?'pending':'ok'}">${ticketStatusLabel(t.status)}</span></div><p>${esc(t.message)}</p>${t.admin_reply?`<div class="notice">Ответ: ${esc(t.admin_reply)}</div>`:''}${t.status==='OPEN'?`<div class="toolbar"><input class="input" data-support-reply="${t.id}" placeholder="Ответ пользователю"><button class="btn small primary" data-support-send="${t.id}">Ответить</button></div>`:''}</div>`).join('')||'<div class="empty">Открытых обращений нет.</div>'}</div></section>`;document.querySelectorAll('[data-support-send]').forEach(b=>b.onclick=()=>doAction(async()=>{const input=document.querySelector(`[data-support-reply="${b.dataset.supportSend}"]`);if(!input.value.trim())throw new Error('Введите ответ');await api('/api/admin/support/'+b.dataset.supportSend+'/reply',{method:'POST',body:{reply:input.value.trim()}})}));document.querySelectorAll('[data-ticket-filter]').forEach(b=>b.onclick=()=>{state.ticketStatus=b.dataset.ticketFilter;loadAdminSection();});}
async function loadAdminBroadcast(root){const h=await api('/api/admin/broadcast/history');root.innerHTML=`<section class="card glass"><div class="section-head">${adminBack()}<h3>📢 Рассылка</h3></div><div class="notice">Текстовая рассылка отправляется всем пользователям бота с обработкой блокировок и RetryAfter.</div><textarea id="broadcastText" class="input textarea" maxlength="4096" placeholder="Текст объявления..."></textarea><button class="btn primary" id="broadcastSend">Отправить всем</button></section><section class="card glass"><div class="section-head"><h3>История</h3></div>${h.items.map(x=>`<div class="admin-row"><div class="grow"><b>${esc(x.type)}</b><div class="sub">${new Date(x.created_at).toLocaleString()}</div></div><span class="pill ok">${x.sent}/${x.total}</span><span class="pill">🚫 ${x.blocked}</span><span class="pill">❌ ${x.failed}</span></div>`).join('')||'<div class="empty">История пуста.</div>'}</section>`;document.getElementById('broadcastSend')?.addEventListener('click',()=>{const text=document.getElementById('broadcastText').value.trim();if(!text)return toast('Введите текст');if(!confirm('Отправить сообщение всем пользователям?'))return;doAction(async()=>api('/api/admin/broadcast',{method:'POST',body:{text}}));});}
async function loadAdminAdmins(root){const r=await api('/api/admin/admins');root.innerHTML=`<section class="card glass"><div class="section-head">${adminBack()}<h3>🛡 Администраторы</h3><span class="count">${r.items.length}</span></div><div class="notice">Можно добавлять несколько администраторов. <b>ADMIN_IDS</b> используется как стартовый список, а новые администраторы сохраняются в БД и переживают перезапуск.</div><div class="admin-manage" style="margin:10px 0"><input id="newAdminId" class="input" inputmode="numeric" placeholder="Telegram ID"><button id="addAdmin" class="btn small primary">Добавить</button></div><div class="list">${r.items.map(a=>`<div class="admin-list-card"><div class="avatar">🛡</div><div class="grow"><b>${esc(a.name)}</b><div class="sub">${a.username?'@'+esc(a.username)+' · ':''}Telegram ID: ${a.telegram_id}</div></div>${a.telegram_id===state.data?.user?.telegram_id?'<span class="pill ok">Вы</span>':`<button class="btn small danger" data-remove-admin="${a.telegram_id}">Удалить</button>`}</div>`).join('')||'<div class="empty">Администраторов нет.</div>'}</div></section>`;document.getElementById('addAdmin')?.addEventListener('click',()=>doAction(async()=>{const id=Number(document.getElementById('newAdminId').value);if(!Number.isInteger(id)||id<=0)throw new Error('Введите корректный Telegram ID');await api('/api/admin/admins',{method:'POST',body:{telegram_id:id}})}));document.querySelectorAll('[data-remove-admin]').forEach(b=>b.onclick=()=>{if(!confirm('Удалить администратора?'))return;doAction(async()=>api('/api/admin/admins/'+b.dataset.removeAdmin,{method:'DELETE'}));});}
async function loadAdminAI(root){
  let status=null;
  try{status=await api('/api/admin/ai/status')}catch(e){}
  const providerHtml=(status?.providers||[]).map(x=>`<span class="pill ${x.configured?'ok':'bad'}">${esc(x.name)} · ${esc(x.model)}${x.configured?'':' · нет ключа'}</span>`).join(' ');
  root.innerHTML=`<section class="card glass ai-panel"><div class="section-head">${adminBack()}<h3>🤖 AI-помощник</h3><span class="pill ${status?.configured?'ok':'bad'}">${status?.configured?'Готов':'Не настроен'}</span></div><div class="notice">AI читает данные проекта через защищённые read-only запросы к БД по мере необходимости. Основной путь — OpenRouter Free Router; при ошибке/квоте сервер автоматически пробует бесплатную Qwen-модель, затем независимый Groq backup, если он настроен. VPN/HTTP-прокси берётся из <b>HTTP_PROXY_URL</b>.</div><div class="ai-providers">${providerHtml||'<span class="pill bad">Нет настроенных провайдеров</span>'}</div><div id="aiMessages" class="ai-messages"></div><div id="aiError" class="error ai-error hidden"></div><div class="ai-compose"><textarea id="aiInput" class="input textarea" maxlength="4000" placeholder="Например: какие команды сейчас зарегистрированы и у кого выше всего подтверждённый средний MMR?"></textarea><div class="toolbar"><button id="aiClear" class="btn small ghost">Очистить</button><button id="aiSend" class="btn primary">Спросить AI</button></div></div></section>`;
  const box=document.getElementById('aiMessages');
  const renderHistory=()=>{box.innerHTML=state.aiHistory.length?state.aiHistory.map(m=>`<div class="ai-message ${m.role==='user'?'ai-user':'ai-assistant'}"><div class="ai-role">${m.role==='user'?'Вы':'AI'}</div><div class="ai-text">${esc(m.content).replace(/\n/g,'<br>')}</div></div>`).join(''):'<div class="empty">Задай вопрос по текущим данным TI:IT TOP.</div>';box.scrollTop=box.scrollHeight;};
  renderHistory();
  const send=async()=>{
    const input=document.getElementById('aiInput'); const q=input?.value.trim(); if(!q)return toast('Введите вопрос');
    input.disabled=true; document.getElementById('aiSend').disabled=true; document.getElementById('aiError')?.classList.add('hidden');
    state.aiHistory.push({role:'user',content:q});
    renderHistory();
    box.insertAdjacentHTML('beforeend',`<div class="ai-message ai-assistant"><div class="ai-role">AI</div><div class="ai-text"><span class="ai-thinking">Подбираю нужные данные…</span></div></div>`);box.scrollTop=box.scrollHeight;
    try{
      const r=await api('/api/admin/ai/ask',{method:'POST',timeout:95000,body:{question:q,history:state.aiHistory.slice(0,-1)}});
      const meta=[];if(r.provider)meta.push(`провайдер: ${r.provider}`);if(r.model)meta.push(`модель: ${r.model}`);if(r.fallback_used)meta.push('аварийный fallback');if(r.tools_used?.length)meta.push(`tools: ${r.tools_used.join(', ')}`);if(meta.length) r.answer=(r.answer||'AI не вернула текст ответа.')+`\n\n[${meta.join(' · ')}]`;
      state.aiHistory.push({role:'assistant',content:r.answer||'AI не вернула текст ответа.'});
      input.value=''; renderHistory();
    }catch(e){ state.aiHistory.pop(); renderHistory(); const err=document.getElementById('aiError'); if(err){err.textContent=errorText(e);err.classList.remove('hidden');} }
    finally{input.disabled=false;document.getElementById('aiSend').disabled=false;input.focus();}
  };
  document.getElementById('aiSend')?.addEventListener('click',send);
  document.getElementById('aiInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}});
  document.getElementById('aiClear')?.addEventListener('click',()=>{state.aiHistory=[];loadAdminAI(root);});
}


