async function loadAdminDiagnostics(root){root.innerHTML=`<section class="card glass"><div class="section-head">${adminBack()}<h3>🌐 Диагностика API</h3><button class="btn small primary" id="diagRun">Проверить</button></div><pre id="diagText" class="diag">Запуск проверки…</pre></section>`;try{const r=await api('/api/admin/diagnostics');document.getElementById('diagText').textContent=r.text||'Пусто';}catch(e){document.getElementById('diagText').textContent=errorText(e);}document.getElementById('diagRun')?.addEventListener('click',()=>loadAdminDiagnostics(root));}
function bindAdminInner(){document.querySelectorAll('[data-admin-section]').forEach(b=>b.onclick=()=>{state.adminSection=b.dataset.adminSection;loadAdminSection();});}

async function loadPlayers(){const box=document.getElementById('playerList');if(!box)return;const q=document.getElementById('search')?.value.trim()||'';box.innerHTML='<div class="search-loading"><span></span><span></span><span></span><b>Ищу игроков…</b></div>';try{const r=await api('/api/players?q='+encodeURIComponent(q));box.innerHTML=r.items.map(p=>{const invited=state.data.team?.is_captain&&(state.data.outgoing_invites||[]).some(i=>i.user_id===p.user_id);return `<article class="player-result"><div class="player-main"><div class="avatar player-avatar">${initials(p.name)}</div><div class="player-info"><div class="player-name">${esc(p.name)}</div>${rankHtml({rank_name:p.rank,rank_tier:p.rank_tier,mmr:p.mmr},true)}<div class="player-positions">${p.positions.length?p.positions.map(x=>`pos ${x}`).join(' · '):'позиции не указаны'}</div></div></div><div class="player-action">${state.data.team?.is_captain?(invited?'<span class="pill pending">Уже приглашён</span>':`<button class="btn small primary" data-player-invite="${p.user_id}">Пригласить</button>`):''}</div></article>`;}).join('')||'<div class="empty">Подходящих свободных игроков нет.</div>';document.querySelectorAll('[data-player-invite]').forEach(b=>b.onclick=()=>doAction(async()=>api('/api/team/invite',{method:'POST',body:{user_id:Number(b.dataset.playerInvite)}})));}catch(e){box.innerHTML=`<div class="error">${esc(errorText(e))}</div>`;}}

async function openTournamentDetail(id){try{content.innerHTML='<div class="loading"><span></span><span></span><span></span></div>';state.tournamentDetail=await api('/api/tournaments/'+id);state.tab='tournaments';render();}catch(e){toast(errorText(e));render();}}

async function load(){content.innerHTML='<div class="loading"><span></span><span></span><span></span></div>';try{state.data=await api('/api/bootstrap');state.data.user.db_user_id=state.data.user.db_user_id||null;render();}catch(e){content.innerHTML=`<div class="error"><b>Не удалось открыть Mini App</b><div style="margin-top:6px">${esc(errorText(e))}</div></div>`;}}
async function doAction(fn){try{await fn();await load();toast('Готово');}catch(e){toast(errorText(e));}}
function bind(){
  document.getElementById('refresh')?.addEventListener('click',load);
  document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>{state.tab=b.dataset.tab;if(state.tab!=='tournaments')state.tournamentDetail=null;if(state.tab!=='admin')state.adminTournamentId=null;render();}));
  document.querySelectorAll('[data-tab-go]').forEach(b=>b.addEventListener('click',()=>{state.tab=b.dataset.tabGo;state.tournamentDetail=null;render();}));
  document.querySelectorAll('[data-tour-open]').forEach(b=>b.addEventListener('click',()=>openTournamentDetail(Number(b.dataset.tourOpen))));
  document.querySelectorAll('[data-tour-back]').forEach(b=>b.addEventListener('click',()=>{state.tournamentDetail=null;render();}));
  bindAdminInner();
  document.getElementById('searchBtn')?.addEventListener('click',loadPlayers);document.getElementById('search')?.addEventListener('keydown',e=>{if(e.key==='Enter')loadPlayers();});
  document.getElementById('createTeam')?.addEventListener('click',()=>doAction(async()=>{const name=document.getElementById('teamName').value.trim();if(!name)throw new Error('Введите название команды');await api('/api/team/create',{method:'POST',body:{name}});}));
  document.getElementById('saveMmr')?.addEventListener('click',()=>doAction(async()=>{const mmr=Number(document.getElementById('mmrInput').value);if(!Number.isInteger(mmr)||mmr<0||mmr>9500)throw new Error('Введите MMR от 0 до 9500');await api('/api/profile/mmr',{method:'POST',body:{mmr}});}));
  document.getElementById('steamRebind')?.addEventListener('click',()=>doAction(async()=>{const steam=document.getElementById('steamRebindInput')?.value.trim();if(!steam)throw new Error('Укажите новый Steam ID или ссылку');await api('/api/profile/steam/rebind',{method:'POST',body:{steam}});}));
  document.getElementById('savePositions')?.addEventListener('click',()=>doAction(async()=>{const positions=[...document.querySelectorAll('[data-pos].active')].map(x=>Number(x.dataset.pos));await api('/api/profile/positions',{method:'POST',body:{positions}});}));
  document.querySelectorAll('[data-pos]').forEach(b=>b.addEventListener('click',()=>b.classList.toggle('active')));
  document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>doAction(async()=>api('/api/invites/'+b.dataset.accept+'/accept',{method:'POST'})));
  document.querySelectorAll('[data-decline]').forEach(b=>b.onclick=()=>doAction(async()=>api('/api/invites/'+b.dataset.decline+'/decline',{method:'POST'})));
  document.querySelectorAll('[data-apply]').forEach(b=>b.onclick=()=>doAction(async()=>{const id=Number(b.dataset.apply);await api('/api/tournaments/'+id+'/apply',{method:'POST'});if(state.tournamentDetail?.id===id)state.tournamentDetail=await api('/api/tournaments/'+id);}));
  document.querySelectorAll('[data-member-pos]').forEach(b=>b.onclick=()=>doAction(async()=>api('/api/team/members/'+b.dataset.memberPos+'/position',{method:'POST',body:{position:Number(b.dataset.value)}})));
  document.getElementById('roleMode')?.addEventListener('change',e=>doAction(async()=>api('/api/team/role-mode',{method:'POST',body:{mode:e.target.value}})));
  document.getElementById('teamAvatarFile')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>8*1024*1024){toast('Файл больше 8 МБ');e.target.value='';return;}if(!(f.type||'').startsWith('image/')){toast('Выбери изображение');e.target.value='';return;}const label=e.target.closest('label');const oldText=label?.firstChild?.textContent;try{if(label?.firstChild)label.firstChild.textContent='⏳ Загружаю…';e.target.disabled=true;const r=await upload('/api/team/avatar/upload',f);toast(r?.telegram_uploaded===false?'✅ Аватар сохранён в веб-приложении':'✅ Аватар команды обновлён');await load();}catch(err){toast(errorText(err));}finally{e.target.disabled=false;if(label?.firstChild&&oldText)label.firstChild.textContent=oldText;e.target.value='';}});
  document.querySelectorAll('[data-avatar-url]').forEach(img=>setAuthImage(img,img.dataset.avatarUrl));
  document.getElementById('deleteTeam')?.addEventListener('click',()=>{const name=state.data?.team?.name||'команду';if(!confirm(`Расформировать «${name}»?\n\nВсе участники будут освобождены, а незавершённые заявки и приглашения удалены.`))return;doAction(async()=>{await api('/api/team/delete',{method:'POST',body:{}});state.tab='team';});});
}
load();
